import { expect, test, uniqueName } from "../../fixtures";

test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
  // Arrange: a draft vendor in the member's tenant
  const member = await apiAs("member");
  const ownVendor = await member.post("/api/vendors", {
    data: { name: uniqueName("Northwind Draft"), category: "services", contact_email: "draft@northwind.example" },
  });
  expect(ownVendor.status(), await ownVendor.text()).toBe(201);
  expect((await ownVendor.json()).status).toBe("draft");

  // Arrange: a document that exists in the Globex tenant
  const other = await apiAs("otherTenant");
  const otherVendor = await other.post("/api/vendors", {
    data: { name: uniqueName("Globex Vendor"), category: "other", contact_email: "ops@globex.example" },
  });
  expect(otherVendor.status(), await otherVendor.text()).toBe(201);
  const { id: otherVendorId } = (await otherVendor.json()) as { id: string };
  const upload = await other.post(`/api/vendors/${otherVendorId}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: Buffer.from("W-9 test form") },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);
  const { id: documentId } = (await upload.json()) as { id: string };

  // Act: the member requests that document by id
  const response = await member.get(`/api/documents/${documentId}`);

  // Assert
  expect(response.status(), await response.text()).toBe(404);
  expect((await response.json()).error.code, await response.text()).toBe("document_not_found");
});
